package com.unicarona.privacy.service;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Bounded expiry for purpose-specific evidence and operational data. Financial journal compaction is separate. */
@Service
public class PrivacyRetentionTransactions {
    private final JdbcTemplate sql;private final PrivacyHoldRecovery recovery;private final PrivacyContractIdentityPurpose identity;private final PrivacyHoldControlTransactions controls;private final PrivacyProtocolRetention protocols;
    public PrivacyRetentionTransactions(JdbcTemplate sql,PrivacyHoldRecovery recovery,PrivacyContractIdentityPurpose identity,PrivacyHoldControlTransactions controls,PrivacyProtocolRetention protocols){this.sql=sql;this.recovery=recovery;this.identity=identity;this.controls=controls;this.protocols=protocols;}
    private void checkpoint(){try{controls.requireCurrentForMaintenance();}catch(java.io.IOException pending){throw new IllegalStateException("Independent preservation control needs recovery before retention.");}}
    @Transactional public void beforeReadiness(){if(!Boolean.TRUE.equals(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM privacy_retained_records WHERE NOT hold_only AND category IN ('contract_identity','vehicle_identity')) OR EXISTS(SELECT 1 FROM privacy_requests WHERE resolved_at<=now()-interval '5 years')",Boolean.class)))return;checkpoint();protocols.expireBeforeReadiness();identity.expireBeforeReadiness();recovery.stage();}
    @Transactional public void prune(int batch){
        if(batch<1||batch>10000)throw new IllegalArgumentException("Invalid retention batch.");
        checkpoint();protocols.expireBatch(batch);identity.expireBatch(batch);
        sql.update("WITH cleared AS (UPDATE privacy_account_closures SET completion_contact_ciphertext=NULL WHERE id IN (SELECT id FROM privacy_account_closures WHERE completion_contact_ciphertext IS NOT NULL AND (notice_contact_expires_at<=now() OR notice_suppressed_at IS NOT NULL) ORDER BY notice_contact_expires_at,id LIMIT ? FOR UPDATE SKIP LOCKED) RETURNING id) INSERT INTO audit_logs(action,resource_type,resource_id,metadata) SELECT 'closure_notice_contact_expired','privacy_account_closure',id,'{\"outcome\":\"transient_contact_removed\"}'::jsonb FROM cleared",batch);
        sql.update("WITH cleared AS (UPDATE outbox_jobs o SET payload='{}',status=CASE WHEN o.status IN ('pending','processing') THEN 'done' ELSE o.status END,completed_at=coalesce(o.completed_at,now()),leased_until=NULL WHERE o.id IN (SELECT j.id FROM outbox_jobs j JOIN privacy_account_closures c ON j.event_key='closure-notice:'||c.id::text||':completed' WHERE j.type='email' AND j.payload<>'{}'::jsonb AND c.notice_contact_expires_at<=now() AND (j.status<>'processing' OR j.leased_until<=now()) ORDER BY j.created_at,j.id LIMIT ? FOR UPDATE OF j SKIP LOCKED) RETURNING o.id) INSERT INTO audit_logs(action,resource_type,resource_id,metadata) SELECT 'closure_notice_payload_expired','email_job',id,'{\"outcome\":\"expired_payload_removed\"}'::jsonb FROM cleared",batch);
        var expiredIdentities=sql.queryForList("SELECT c.id,c.token_id FROM privacy_email_changes c JOIN users u ON u.id=c.user_id WHERE c.status='pending' AND c.expires_at<=now() ORDER BY u.id,c.id LIMIT ? FOR UPDATE OF u,c SKIP LOCKED",batch);
        for(var entry:expiredIdentities){
            sql.update("UPDATE auth_tokens SET invalidated_at=coalesce(invalidated_at,now()),used_at=coalesce(used_at,now()) WHERE id=?",entry.get("token_id"));
            sql.update("UPDATE privacy_email_changes SET status='expired',completed_at=now(),credential_hmac=NULL WHERE id=?",entry.get("id"));
        }
        sql.update("UPDATE privacy_email_changes c SET new_email_ciphertext=NULL WHERE c.id IN (SELECT e.id FROM privacy_email_changes e WHERE e.status<>'pending' AND e.new_email_ciphertext IS NOT NULL AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.category='identity_change' AND h.released_at IS NULL AND h.expires_at>now() AND (h.resource_id IS NULL OR h.resource_id=e.id)) ORDER BY e.created_at,e.id LIMIT ? FOR UPDATE OF e SKIP LOCKED)",batch);
        sql.update("DELETE FROM privacy_email_changes c WHERE c.id IN (SELECT e.id FROM privacy_email_changes e WHERE e.status<>'pending' AND e.created_at<now()-interval '30 days' AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.category='identity_change' AND h.released_at IS NULL AND h.expires_at>now() AND (h.resource_id IS NULL OR h.resource_id=e.id)) ORDER BY e.created_at,e.id LIMIT ? FOR UPDATE OF e SKIP LOCKED)",batch);
        sql.update("DELETE FROM privacy_account_decisions d WHERE d.id IN (SELECT e.id FROM privacy_account_decisions e WHERE e.retain_until<=now() AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.category='account_decision' AND h.released_at IS NULL AND h.expires_at>now() AND (h.resource_id IS NULL OR h.resource_id=e.id)) ORDER BY e.retain_until,e.id LIMIT ? FOR UPDATE OF e SKIP LOCKED)",batch);
        sql.update("DELETE FROM privacy_retained_records r WHERE r.id IN (SELECT e.id FROM privacy_retained_records e WHERE (e.delete_after<=now() OR e.hold_only) AND NOT (NOT e.hold_only AND e.category IN ('contract_identity','vehicle_identity')) AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.released_at IS NULL AND h.expires_at>now() AND (h.category=e.category OR (h.category='financial' AND e.category IN ('contract_identity','vehicle_identity'))) AND (h.resource_id IS NULL OR h.resource_id=e.resource_id)) ORDER BY e.delete_after,e.id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        sql.update("DELETE FROM privacy_consent_events c WHERE c.id IN (SELECT e.id FROM privacy_consent_events e WHERE e.retain_until<=now() AND (NOT coalesce((SELECT p.marketing FROM privacy_preferences p WHERE p.user_id=e.user_id),false) OR EXISTS(SELECT 1 FROM privacy_consent_events newer WHERE newer.user_id=e.user_id AND newer.purpose=e.purpose AND (newer.created_at,newer.id)>(e.created_at,e.id))) AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.category='consent' AND h.released_at IS NULL AND h.expires_at>now() AND (h.resource_id IS NULL OR h.resource_id=e.id)) ORDER BY e.retain_until,e.id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        sql.update("UPDATE legal_acceptances SET ip_ciphertext=NULL,ip_delete_after=NULL WHERE id IN (SELECT id FROM legal_acceptances WHERE ip_delete_after<=now() ORDER BY ip_delete_after,id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        sql.update("DELETE FROM legal_acceptances a WHERE a.id IN (SELECT e.id FROM legal_acceptances e JOIN users u ON u.id=e.user_id WHERE e.retain_until<=now() AND u.deleted_at<=now()-interval '5 years' AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.category='legal' AND h.released_at IS NULL AND h.expires_at>now() AND (h.resource_id IS NULL OR h.resource_id=e.id)) ORDER BY e.retain_until,e.id LIMIT ? FOR UPDATE OF e SKIP LOCKED)",batch);
        sql.update("DELETE FROM legal_change_notices n WHERE (n.user_id,n.document_slug,n.document_version) IN (SELECT e.user_id,e.document_slug,e.document_version FROM legal_change_notices e JOIN users u ON u.id=e.user_id WHERE u.deleted_at<=now()-interval '5 years' AND e.notified_at<=now()-interval '5 years' AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.category='legal' AND h.released_at IS NULL AND h.expires_at>now() AND (h.resource_id IS NULL OR EXISTS(SELECT 1 FROM legal_acceptances a WHERE a.id=h.resource_id AND a.user_id=e.user_id AND a.document_slug=e.document_slug AND a.document_version=e.document_version))) ORDER BY e.notified_at,e.user_id LIMIT ? FOR UPDATE OF e SKIP LOCKED)",batch);
        sql.update("UPDATE outbox_jobs SET payload='{}' WHERE id IN (SELECT id FROM outbox_jobs WHERE type='email' AND status='done' AND payload<>'{}'::jsonb ORDER BY completed_at,id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        sql.update("UPDATE outbox_jobs SET payload='{}' WHERE id IN (SELECT o.id FROM outbox_jobs o WHERE o.type='email' AND o.status='dead' AND o.created_at<now()-interval '30 days' AND o.payload<>'{}'::jsonb ORDER BY o.created_at,o.id LIMIT ? FOR UPDATE OF o SKIP LOCKED)",batch);
        sql.update("DELETE FROM auth_tokens WHERE id IN (SELECT id FROM auth_tokens WHERE expires_at<now()-interval '30 days' ORDER BY expires_at,id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        sql.update("DELETE FROM idempotency_keys WHERE (actor_id,key,scope) IN (SELECT actor_id,key,scope FROM idempotency_keys WHERE expires_at<=now() ORDER BY expires_at,actor_id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        sql.update("DELETE FROM sessions WHERE family_id IN (SELECT family_id FROM sessions GROUP BY family_id HAVING max(refresh_expires_at)<now()-interval '30 days' ORDER BY max(refresh_expires_at) LIMIT ?)",batch);
        sql.update("DELETE FROM notifications n WHERE n.id IN (SELECT e.id FROM notifications e WHERE e.created_at<now()-interval '90 days' AND NOT EXISTS(SELECT 1 FROM privacy_legal_holds h WHERE h.user_id=e.user_id AND h.category='notifications' AND h.released_at IS NULL AND h.expires_at>now() AND (h.resource_id IS NULL OR h.resource_id=e.id)) ORDER BY e.created_at,e.id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        sql.update("DELETE FROM privacy_hold_events e WHERE e.id IN (SELECT v.id FROM privacy_hold_events v JOIN privacy_legal_holds h ON h.id=v.hold_id WHERE v.retain_until<=now() AND (h.released_at IS NOT NULL OR h.expires_at<=now()) ORDER BY v.retain_until,v.id LIMIT ? FOR UPDATE OF v SKIP LOCKED)",batch);
        sql.update("DELETE FROM privacy_legal_holds h WHERE h.id IN (SELECT v.id FROM privacy_legal_holds v WHERE v.retain_until<=now() AND (v.released_at IS NOT NULL OR v.expires_at<=now()) AND NOT EXISTS(SELECT 1 FROM privacy_hold_events e WHERE e.hold_id=v.id) ORDER BY v.retain_until,v.id LIMIT ? FOR UPDATE OF v SKIP LOCKED)",batch);
        sql.update("DELETE FROM privacy_registration_restrictions WHERE id IN (SELECT id FROM privacy_registration_restrictions WHERE expires_at<=now() OR released_at IS NOT NULL ORDER BY expires_at,id LIMIT ? FOR UPDATE SKIP LOCKED)",batch);
        recovery.stage();
    }
}
